const root=resolve(dirname(fileURLToPath(import.meta.url)),'..'),fixture=await mkdtemp(resolve(root,'scripts/.publish-test-'));
let admins=[],approved=[],published=[],patches=[],creditRows=[],requests=[],race=null,readRace=null,failPatch=null,nextId=10000;
const server=createServer(async(req,res)=>{let body='';for await(const chunk of req)body+=chunk;
 const url=new URL(req.url,'http://fixture'),q=url.searchParams;requests.push({method:req.method,url:req.url,body:body?JSON.parse(body):null});
 if(url.pathname==='/rest/v1/admins'){res.end(JSON.stringify(admins));return;}
 if(url.pathname==='/rest/v1/credits'){if(req.method==='POST'){for(const c of JSON.parse(body))if(!creditRows.some(r=>r.suggestion_id===c.suggestion_id))creditRows.push(c);res.statusCode=201;res.end();}else res.end(JSON.stringify(creditRows.slice(Number(q.get('offset')||0),Number(q.get('offset')||0)+1000)));return;}
 if(req.method==='POST'&&url.pathname==='/rest/v1/suggestions'){const row={...JSON.parse(body),id:nextId++,updated_at:'2026-10-10T14:00:00Z'};approved.push(row);res.statusCode=201;res.end(JSON.stringify([row]));return;}
 if(req.method==='GET'&&readRace)readRace(q);
 const id=q.get('id'),status=q.get('status')?.slice(3),source=status==='published'?published:status?approved:[...published,...approved];
 let rows=source.map(r=>({...r,status:r.status||'approved'})).filter(r=>(!id||id.startsWith('gt.')?Number(r.id)>Number(id?.slice(3)||0):String(r.id)===id.slice(3))&&(!status||r.status===status)&&(!q.get('review_note')||r.review_note===q.get('review_note').slice(3)));
 if(req.method==='PATCH'){
  if(race){race();race=null;rows=approved.filter(r=>String(r.id)===id?.slice(3)&&r.status==='approved');}
  if(failPatch&&failPatch(q,JSON.parse(body))){res.statusCode=400;res.end();return;}
  patches.push(JSON.parse(body));const payload=q.get('payload')?.slice(3),version=q.get('updated_at')?.slice(3);
  rows=rows.filter(r=>(!payload||JSON.stringify(r.payload)===payload)&&(!version||r.updated_at===version));
  for(const r of rows){const original=approved.find(a=>a.id===r.id);Object.assign(original,JSON.parse(body));if(original.status==='published'){published.push({...original});approved=approved.filter(a=>a.id!==r.id);}}
  res.end(JSON.stringify(rows.map(r=>({id:r.id}))));
 }else res.end(JSON.stringify(rows.slice(0,Number(q.get('limit')||1000))));});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
// Ordinary retries model a failed push: discard the uncommitted run log. Recovery keeps the committed log.
async function run(mode=false){
 if(mode!==true&&mode!=='mark'&&mode!=='recover')await rm(fixture+'/data/publish-log.json',{force:true});
 const execute=argument=>new Promise((resolve,reject)=>{const child=spawn(process.execPath,[fixture+'/scripts/apply-approved.mjs',...argument],{cwd:fixture,env:{...process.env,SUPABASE_URL:'http://127.0.0.1:'+server.address().port,SUPABASE_SERVICE_KEY:'test-secret'}});let output='';child.stdout.on('data',d=>output+=d);child.stderr.on('data',d=>output+=d);child.on('error',reject);child.on('exit',code=>resolve({code,output}));});
 const result=await execute(mode==='mark'?['--mark-published','.publish/applied.json']:mode===true?['--dry-run']:[]);
 if(mode!==true&&mode!=='mark'&&result.code===0){
  const holds=JSON.parse(await readFile(fixture+'/.publish/held.json','utf8'));
  if(holds.length){
   await writeFile(fixture+'/.publish/holds-only.json','[]');
   const marked=await execute(['--mark-published','.publish/holds-only.json']);
   result.code=marked.code;result.output+=marked.output;
  }
 }
 return result;
}

